/*1.科目变更数据准备*/
/*1.1 创建临时表:初始化待科目变更数据*/
create table SJZL_SUBJECT_CHANGE
(
row_index_no    NUMBER(10),
bookset_id      VARCHAR2(50),
subject_no      VARCHAR2(32),
subject_name    VARCHAR2(200),
re_subject_no   VARCHAR2(32),
re_subject_name VARCHAR2(200),
task_pri        NUMBER(10),
finprod_type    VARCHAR2(50),
trade_market    VARCHAR2(50),
type_2          VARCHAR2(50),
is_qtzq         VARCHAR2(50)
);
comment on column SJZL_SUBJECT_CHANGE.row_index_no is '行号';
comment on column SJZL_SUBJECT_CHANGE.bookset_id is '账套代码';
comment on column SJZL_SUBJECT_CHANGE.subject_no is '原科目号';
comment on column SJZL_SUBJECT_CHANGE.subject_name is '原科目名称';
comment on column SJZL_SUBJECT_CHANGE.re_subject_no is '科目号';
comment on column SJZL_SUBJECT_CHANGE.re_subject_name is '科目名称';
comment on column SJZL_SUBJECT_CHANGE.task_pri is '执行顺序';
comment on column SJZL_SUBJECT_CHANGE.finprod_type is '金融产品类型';
comment on column SJZL_SUBJECT_CHANGE.trade_market is '交易场所';
comment on column SJZL_SUBJECT_CHANGE.type_2 is '核算分类';
comment on column SJZL_SUBJECT_CHANGE.is_qtzq is '是否其他债权';
COMMIT;
/*1.2 创建临时表：根据初始生成的科目变更信息提取待处理数据*/
CREATE TABLE BOK_BOOKDETAIL_CURRENT_CL AS
SELECT
J.*,
S.RE_SUBJECT_NO,
S.RE_SUBJECT_NAME,
S.TASK_PRI
FROM SJZL_SUBJECT_CHANGE S,(
SELECT DISTINCT A.BOOKSET_ID,
B.BUSI_ID,
A.SUBJECT_NO,
A.DETAIL_SUBJECT_NO,
B.BUSI_DETAIL_TYPE,
B.DETAIL_SUBJECT_NO_TAIL,
B.DETAIL_SUBNAME_TAIL,
A.BOK_DETAIL_ID,
B.BRANCH,
H.TRADE_MARKET,
H.IS_QTZQ,
H.TYPE_2
FROM BOK_BOOKDETAIL_CURRENT A
LEFT JOIN BOK_DETAIL_ID B
ON A.BOOKSET_ID = B.BOOKSET_ID
AND A.BOK_DETAIL_ID = B.BOK_DETAIL_ID
LEFT JOIN BOK_BOOKSET C
ON A.BOOKSET_ID = C.BOOKSET_ID
LEFT JOIN (SELECT D.FINPROD_ID,
D.FINPROD_TYPE,
D.TRADE_MARKET,
NVL(E.IS_QTZQ, 'N') IS_QTZQ,
F.TYPE_2
FROM FIN_PRODUCT D
LEFT JOIN FIN_PRODUCT_ADD E
ON D.FINPROD_ID = E.FINPROD_ID
LEFT JOIN FIN_PRODUCT_TYPE F
ON D.FINPROD_ID = F.FINPROD_ID
UNION ALL
SELECT G.FINPROD_ID,
G.FINPROD_TYPE,
G.TRADE_MARKET,
'N' IS_QTZQ,
F.TYPE_2
FROM FIN_TRADE_PRODUCT G
LEFT JOIN FIN_PRODUCT_TYPE F
ON G.FINPROD_ID = F.FINPROD_ID
AND G.BRANCH = F.BRANCH
WHERE G.BRANCH = 0
AND G.FINPROD_TYPE != 'F21') H
ON B.BUSI_ID = H.FINPROD_ID
) J
WHERE S.SUBJECT_NO = J.SUBJECT_NO
AND NVL(S.BOOKSET_ID,'null') = CASE WHEN S.BOOKSET_ID IS NULL THEN 'null' ELSE J.BOOKSET_ID END
AND NVL(S.FINPROD_TYPE,'null') = CASE WHEN S.FINPROD_TYPE IS NULL THEN 'null' ELSE J.BUSI_DETAIL_TYPE END
AND NVL(S.TRADE_MARKET,'null') = CASE WHEN S.TRADE_MARKET IS NULL THEN 'null' ELSE J.TRADE_MARKET END
AND NVL(S.IS_QTZQ,'null') = CASE WHEN S.IS_QTZQ IS NULL THEN 'null' ELSE J.IS_QTZQ END
AND NVL(S.TYPE_2,'null') = CASE WHEN S.TYPE_2 IS NULL THEN 'null' ELSE J.TYPE_2 END
ORDER BY S.TASK_PRI
;
/*2.开始-业务数据更新*/
/*2.1 业务明细科目表数据*/
BOOKSET_ID,DETAIL_SUBJECT_NO,DETAIL_SUBJECT_NAME,
FSUBJECT_ID,CREATE_USER,CREATE_DEPT,CREATE_TIME,
UPDATE_USER,UPDATE_TIME,DETAIL_SUBJECT_NO_TAIL,DETAIL_SUBNAME_TAIL
)
SELECT
DISTINCT
A.BOOKSET_ID,
A.RE_SUBJECT_NO||A.DETAIL_SUBJECT_NO AS DETAIL_SUBJECT_NO,
A.RE_SUBJECT_NAME||A.DETAIL_SUBNAME_TAIL AS DETAIL_SUBJECT_NAME,
A.RE_SUBJECT_NO AS FSUBJECT_ID,
'sjzl',
null,
SYSDATE,
'sjzl',
SYSDATE,
A.DETAIL_SUBJECT_NO,
A.DETAIL_SUBNAME_TAIL
FROM BOK_BOOKDETAIL_CURRENT_CL A
WHERE A.DETAIL_SUBJECT_NO IS NOT NULL
AND NOT EXISTS(
SELECT 1 FROM BOK_BUSS_DETSUB B WHERE A.BOOKSET_ID = B.BOOKSET_ID
AND A.RE_SUBJECT_NO||A.DETAIL_SUBJECT_NO = B.DETAIL_SUBJECT_NO
);
COMMIT;
/*2.2 账务明细历史表、账务明细当前表、增值税计税流水表数据*/
DECLARE
  CURSOR LIST IS 
         SELECT
           BOOKSET_ID,BUSI_ID,SUBJECT_NO,DETAIL_SUBJECT_NO,BUSI_DETAIL_TYPE,DETAIL_SUBJECT_NO_TAIL,
           DETAIL_SUBNAME_TAIL,BOK_DETAIL_ID,BRANCH,TRADE_MARKET,IS_QTZQ,TYPE_2,RE_SUBJECT_NO,
           RE_SUBJECT_NAME,TASK_PRI
         FROM BOK_BOOKDETAIL_CURRENT_CL ORDER BY TASK_PRI;
  BEGIN
  FOR item IN LIST
  LOOP
    /*账务明细历史表*/
    UPDATE BOK_BOOKDETAIL_ALL SET
       SUBJECT_NO=item.RE_SUBJECT_NO,
       DETAIL_SUBJECT_NO =CASE WHEN DETAIL_SUBJECT_NO IS NULL THEN NULL ELSE item.RE_SUBJECT_NO||item.DETAIL_SUBJECT_NO_TAIL END,
       UPDATE_USER ='sjzl',
       UPDATE_TIME = SYSDATE
    WHERE BOOKSET_ID = item.BOOKSET_ID
    AND BOK_DETAIL_ID = item.BOK_DETAIL_ID
    AND SUBJECT_NO = item.SUBJECT_NO;
    /*账务明细当前表*/
    UPDATE BOK_BOOKDETAIL_CURRENT SET
       SUBJECT_NO=item.RE_SUBJECT_NO,
       DETAIL_SUBJECT_NO =CASE WHEN DETAIL_SUBJECT_NO IS NULL THEN NULL ELSE item.RE_SUBJECT_NO||item.DETAIL_SUBJECT_NO_TAIL END,
       UPDATE_USER ='sjzl',
       UPDATE_TIME = SYSDATE
    WHERE BOOKSET_ID = item.BOOKSET_ID
    AND BOK_DETAIL_ID = item.BOK_DETAIL_ID
    AND SUBJECT_NO = item.SUBJECT_NO;
    /*增值税计税流水*/
    UPDATE TAX_BOK_DETAIL  SET
       SUBJECT_NO=item.RE_SUBJECT_NO,
       UPDATE_USER ='sjzl',
       UPDATE_TIME = SYSDATE
    WHERE BOOKSET_ID = item.BOOKSET_ID
    AND BOK_DETAIL_ID = item.BOK_DETAIL_ID
    AND SUBJECT_NO = item.SUBJECT_NO;
    COMMIT;
  END LOOP;
END;
/
/*3.结束-业务数据更新，数据验证通过后，删除过程使用的临时表*/
DROP TABLE BOK_BOOKDETAIL_CURRENT_CL;
DROP TABLE SJZL_SUBJECT_CHANGE;